//! BW-10-02-01 acceptance evidence: a genuine `space.bin` produced by the
//! ORIGINAL BigWorld `compiled_space` writer code parses identically here.
//!
//! The fixture `docs/review/fixtures/compiled_space/space.bin` (340 bytes) was
//! generated by compiling `binary_writers/{binary_format,string_table_writer,
//! asset_list_writer,settings_writer}.cpp` from the reference tree natively on
//! Linux (against the reference's own `libcstdmf`/`libmath`/`libresmgr`) and
//! running `gen_space.cpp` in the same directory. The reference
//! `tools/asset_pipeline` space_converter cannot run on Linux (its CMake
//! FATAL_ERRORs off Windows), so the same writer code is exercised directly.
//!
//! Quirks the fixture carries and the tests pin:
//! - `Header::file_size` is 0 — the original writer never sets it;
//! - the `BWAL` entries carry uninitialized padding bytes;
//! - the duplicate model asset was deduplicated by the writer (3 assets, but
//!   4 strings, since the chunk path string is unreferenced by the list).

use compiled_space::{AssetList, BinaryFormat, CompiledSpaceSettings, StringTable};

fn fixture_bytes() -> Vec<u8> {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../docs/review/fixtures/compiled_space/space.bin");
    std::fs::read(path).expect("space.bin fixture readable")
}

#[test]
fn container_header_and_section_table_match_the_original() {
    let bytes = fixture_bytes();
    assert_eq!(bytes.len(), 340);

    let format = BinaryFormat::open("space.bin", bytes).unwrap();
    let header = format.header();
    assert_eq!(header.magic, *b"BWTB");
    assert_eq!(header.version, 1);
    assert_eq!(header.header_size, 96);
    // The writer memsets the header and never fills fileSize_.
    assert_eq!(header.file_size, 0);
    assert_eq!(header.num_sections, 3);
    assert_eq!(format.num_sections(), 3);

    // Sections in append order: BWST, BWAL, BWCS; offsets are absolute and
    // start right after the 24 + 3*24 byte table.
    let expected = [
        (*b"BWST", 1u32, 96u64, 184u64),
        (*b"BWAL", 1, 280, 32),
        (*b"BWCS", 1, 312, 28),
    ];
    for (i, (magic, version, offset, length)) in expected.iter().enumerate() {
        assert_eq!(format.section_magic(i), Some(*magic));
        assert_eq!(format.section_version(i), Some(*version));
        assert_eq!(format.section_length(i), Some(*length));
        // The section stream starts at the declared absolute offset.
        let mut stream = format.open_section(i).unwrap();
        assert_eq!(stream.length(), *length as usize);
        assert_eq!(
            stream.read_raw(*length as usize).map(<[u8]>::len),
            Some(*length as usize)
        );
        // Payloads are contiguous: 96+184=280, 280+32=312, 312+28=340.
        let end = offset + length;
        assert_eq!(end, expected.get(i + 1).map_or(340, |next| next.2));
    }

    assert_eq!(format.find_section(*b"BWST"), Some(0));
    assert_eq!(format.find_section(*b"BWAL"), Some(1));
    assert_eq!(format.find_section(*b"BWCS"), Some(2));
    assert_eq!(format.find_section(*b"NOPE"), None);
}

#[test]
fn string_table_holds_the_four_writer_strings() {
    let bytes = fixture_bytes();
    let format = BinaryFormat::open("space.bin", bytes).unwrap();
    let table = StringTable::read(&format).unwrap();

    assert!(table.is_valid());
    assert_eq!(table.size(), 4);

    let expected = [
        ("spaces/sample_set/spaces/01.model", 33u32),
        ("spaces/sample_set/textures/grass.tga", 36),
        ("shaders/std_effects/light_only.fx", 33),
        ("spaces/sample_set/chunks/001.chunk", 34),
    ];
    for (i, (text, length)) in expected.iter().enumerate() {
        assert_eq!(table.entry_str(i), Some(*text));
        assert_eq!(table.entry_length(i), Some(*length));
    }

    // Offsets are NUL-to-NUL: each entry starts one past the previous end.
    let offsets = [0u32, 34, 71, 105];
    for (i, offset) in offsets.iter().enumerate() {
        assert_eq!(table.entries()[i].offset, *offset);
    }
    assert_eq!(table.entry_bytes(4), None);
    assert_eq!(table.entry_str(4), None);
}

#[test]
fn asset_list_holds_the_three_deduplicated_assets() {
    let bytes = fixture_bytes();
    let format = BinaryFormat::open("space.bin", bytes).unwrap();
    let assets = AssetList::read(&format).unwrap();

    // The writer deduplicated the repeated model path: 3 assets for 4 strings.
    assert!(assets.is_valid());
    assert_eq!(assets.size(), 3);
    assert!(!assets.is_empty());

    let expected = [
        (
            compiled_space::ASSET_TYPE_MODEL,
            "spaces/sample_set/spaces/01.model",
        ),
        (
            compiled_space::ASSET_TYPE_TEXTURE,
            "spaces/sample_set/textures/grass.tga",
        ),
        (
            compiled_space::ASSET_TYPE_EFFECT,
            "shaders/std_effects/light_only.fx",
        ),
    ];
    for (i, (asset_type, name)) in expected.iter().enumerate() {
        assert_eq!(assets.asset_type(i), Some(*asset_type));
        assert_eq!(assets.string_table_index(i), Some(i as u32));
        assert_eq!(
            table_name(&format, assets.string_table_index(i).unwrap()),
            *name
        );
    }
    assert_eq!(assets.asset_type(3), None);

    // The chunk path string is present in the table but never referenced by
    // the asset list.
    assert_eq!(table_name(&format, 3), "spaces/sample_set/chunks/001.chunk");
}

fn table_name(format: &BinaryFormat, index: u32) -> &str {
    StringTable::read(format)
        .unwrap()
        .entry_str(index as usize)
        .unwrap()
}

#[test]
fn settings_hold_the_converter_bounds() {
    let bytes = fixture_bytes();
    let format = BinaryFormat::open("space.bin", bytes).unwrap();
    let settings = CompiledSpaceSettings::read(&format).unwrap();

    let bounds = settings.bounding_box();
    assert_eq!(bounds.min.x, -50.0);
    assert_eq!(bounds.min.y, -10.0);
    assert_eq!(bounds.min.z, -50.0);
    assert_eq!(bounds.max.x, 50.0);
    assert_eq!(bounds.max.y, 30.0);
    assert_eq!(bounds.max.z, 50.0);
}
